cd /workspace/graphic && python3 - <<'EOF'
p='css/template.css'; s=open(p).read()
s=s.replace('''  display: block;
  width: 100%;                     /* the label owns the row's middle, so it never reads as overflowing */''','''  display: -webkit-box;            /* the label states its own room: two rows at most, never resized */
